"""PCB thermal studies grouped with related Wisk work."""
from pathlib import Path

def publish_pages(root):
    root=Path(root)
    for name in ['battery-thermal-icepak.html','battery-thermal.html','battery-thermal-cad.html','battery-thermal-stage-02.html','battery-thermal-stage-03.html','battery-thermal-stage-04.html','battery-thermal-stage-05.html','battery-thermal-stage-06.html','battery-thermal-stage-07.html']:
        (root/'AISolutions'/name).write_text((root/'scripts/content'/name).read_text())

def battery_thermal_card():
    return '''<article class="simulation-card filter-item" id="battery-thermal" data-category="Thermal" data-method="systems" data-analysis-company-ids="wisk-experience"><div class="card-copy"><p class="eyebrow">Wisk work / Battery thermal modeling</p><h2>Battery thermal modeling, step by step</h2><p>Start with one cell, then build a coupled PCB and enclosure model. The latest stage compares adhesive thicknesses under the largest graphite sheet, tracking cover and battery temperatures with a separate resistance-only diagnostic.</p><div class="pills"><span>FreeCAD</span><span>Python</span><span>SciPy</span><span>Open source</span></div><p class="study-note">Stages 01–07 available · Adhesive thickness and thermal coupling · Layered finite volumes and lumped packages · Assumed inputs · Numerically verified, not experimentally validated.</p></div><a class="analysis-research-image" href="/AISolutions/battery-thermal-stage-07.html" aria-label="Open the adhesive thickness comparison"><img src="/assets/studies/battery-thermal/stage-07/figures/adhesive_maps.png" alt="Back-cover and battery maps for three adhesive thicknesses" loading="lazy" width="1760" height="1440"></a><div class="card-bottom"><a class="text-link" href="/AISolutions/battery-thermal.html">Start with Stage 01 →</a><a class="text-link" href="/AISolutions/battery-thermal-stage-02.html">Compare heat input →</a><a class="text-link" href="/AISolutions/battery-thermal-stage-03.html">Explore PCB &amp; enclosure →</a><a class="text-link" href="/AISolutions/battery-thermal-stage-04.html">Compare the RF cooling pad →</a><a class="text-link" href="/AISolutions/battery-thermal-stage-05.html">Explore graphite spreading →</a><a class="text-link" href="/AISolutions/battery-thermal-stage-06.html">Compare graphite sizes →</a><a class="text-link" href="/AISolutions/battery-thermal-stage-07.html">Compare adhesive thickness →</a></div></article>'''


